        let row: list[int] = matrix[i].unwrap()
        let mut s: int = 0
        let mut j: int = 0
        while j < row.len() {
            s = s + row[j].unwrap()
            j = j + 1
        }
        sums = sums.push(s)
        i = i + 1
    }
    return sums
}

