fn char_histogram(s: str) to list[(str, int)] {
    let mut keys: list[str] = []
    let mut counts: list[int] = []
    let mut i: int = 0
    while i < s.len() {
        let ch: str = s.slice(i, i + 1)
        let mut found: bool = false
        let mut k: int = 0
        while k < keys.len() {
            if keys[k].unwrap() == ch {
                counts[k] = counts[k].unwrap() + 1
                found = true
            }
            k = k + 1
        }
        if not found {
            keys = keys.push(ch)
            counts = counts.push(1)
        }
        i = i + 1
    }
    let mut out: list[(str, int)] = []
    let mut m: int = 0
    while m < keys.len() {
        out = out.push((keys[m].unwrap(), counts[m].unwrap()))
        m = m + 1
    }
    return out
}

