fn balanced_multi_brackets(s: str) to bool {
    let mut stack: list[str] = []
    let mut i: int = 0
    while i < s.len() {
        let ch: str = s.slice(i, i + 1)
        if ch == "(" or ch == "[" or ch == "{" {
            stack = stack.push(ch)
        } else if ch == ")" or ch == "]" or ch == "}" {
            if stack.len() == 0 {
                return false
            }
            let top: str = stack[stack.len() - 1].unwrap()
            let matches: bool = (ch == ")" and top == "(") or (ch == "]" and top == "[") or (ch == "}" and top == "{")
            if not matches {
                return false
            }
            stack = stack.slice(0, stack.len() - 1)
        }
        i = i + 1
    }
    return stack.len() == 0
}

